#include <immintrin.h>
typedef struct { double d[6]; int i[36]; } state_t;
typedef void (*naupd_t)(state_t*, double*, double*, int, int*, double*, double*);

/* SELL-4 format: nb = ceil(n/4) blocks; bptr[b] = start (in units of 4 entries) ;
   vals/idx laid out [entry][lane] */
static void spmv(int n, int nb, const int* bptr, const int* idx, const double* vals,
                 const double* x, double* y)
{
  for (int b = 0; b < nb; b++) {
    int s = bptr[b], e = bptr[b+1];
    __m256d acc = _mm256_setzero_pd();
    for (int t = s; t < e; t++) {
      __m128i ii = _mm_loadu_si128((const __m128i*)(idx + 4*t));
      __m256d xv = _mm256_i32gather_pd(x, ii, 8);
      __m256d vv = _mm256_loadu_pd(vals + 4*t);
      acc = _mm256_add_pd(acc, _mm256_mul_pd(vv, xv));
    }
    if (4*b + 4 <= n) _mm256_storeu_pd(y + 4*b, acc);
    else {
      double tmp[4]; _mm256_storeu_pd(tmp, acc);
      for (int r = 4*b; r < n; r++) y[r] = tmp[r - 4*b];
    }
  }
}

int run_loop(void* fn, state_t* st, int n, int nb, const int* bptr, const int* idx, const double* vals,
             double* resid, double* v, int* ipntr, double* workd, double* workl)
{
  naupd_t f = (naupd_t)fn;
  for (;;) {
    f(st, resid, v, n, ipntr, workd, workl);
    int ido = st->i[1];
    if (ido == 1 || ido == 5 || ido == -1) {
      spmv(n, nb, bptr, idx, vals, workd + ipntr[0], workd + ipntr[1]);
    } else if (ido == 2) {
      const double* x = workd + ipntr[0];
      double* y = workd + ipntr[1];
      for (int r = 0; r < n; r++) y[r] = x[r];
    } else {
      return ido;
    }
  }
}
